// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title IHub
/// @author Relay Protocol
/// @notice Interface for the Hub contract
interface IHub {
  /// @notice Returns the balance of a token for an owner
  /// @param owner The owner address
  /// @param id The token ID
  /// @return The balance amount
  function balanceOf(address owner, uint256 id) external view returns (uint256);

  /// @notice Transfers tokens from one address to another
  /// @param sender The sender address
  /// @param receiver The receiver address
  /// @param id The token ID
  /// @param amount The amount to transfer
  /// @return True if successful
  function transferFrom(
    address sender,
    address receiver,
    uint256 id,
    uint256 amount
  ) external returns (bool);

  /// @notice Returns the total supply of a token
  /// @param id The token ID
  /// @return The total supply
  function totalSupply(uint256 id) external view returns (uint256);

  /// @notice Returns the name of a token
  /// @param id The token ID
  /// @return The token name
  function name(uint256 id) external view returns (string memory);

  /// @notice Returns the symbol of a token
  /// @param id The token ID
  /// @return The token symbol
  function symbol(uint256 id) external view returns (string memory);

  /// @notice Returns the decimals of a token
  /// @param id The token ID
  /// @return The token decimals
  function decimals(uint256 id) external view returns (uint8);

  /// @notice Returns the token URI of a token
  /// @param id The token ID
  /// @return The token URI
  function tokenURI(uint256 id) external view returns (string memory);

  /// @notice Returns the allowance of a spender for an owner
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param id The token ID
  /// @return The allowance amount
  function allowance(
    address owner,
    address spender,
    uint256 id
  ) external view returns (uint256);

  /// @notice Approves a spender to spend tokens on behalf of owner
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param id The token ID
  /// @param amount The amount to approve
  /// @return True if successful
  function approveFor(
    address owner,
    address spender,
    uint256 id,
    uint256 amount
  ) external returns (bool);
}

/// @title ERC20View
/// @author Relay Protocol
/// @notice ERC20-compatible view contract that interfaces with the Hub
contract ERC20View {
  /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

  /// @notice Emitted when an approval is made
  event Approval(address indexed owner, address indexed spender, uint256 value);
  /// @notice Emitted when a transfer occurs
  event Transfer(address indexed from, address indexed to, uint256 value);

  /*//////////////////////////////////////////////////////////////
                            CUSTOM ERRORS
    //////////////////////////////////////////////////////////////*/

  error ERC20ViewInsufficientAllowance(
    address spender,
    uint256 allowance,
    uint256 needed
  );

  /*//////////////////////////////////////////////////////////////
                                STORAGE
    //////////////////////////////////////////////////////////////*/

  /// @notice The Hub contract instance
  IHub public immutable hub;
  /// @notice The token ID this view represents
  uint256 public immutable tokenId;

  /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

  /// @notice Constructor for ERC20View
  /// @param _tokenId The token ID this view represents
  constructor(uint256 _tokenId) {
    hub = IHub(msg.sender);
    tokenId = _tokenId;
  }

  /*//////////////////////////////////////////////////////////////
                          ERC20 IMPLEMENTATION
    //////////////////////////////////////////////////////////////*/

  /// @notice Returns the name of the token
  /// @return The token name
  function name() public view returns (string memory) {
    return hub.name(tokenId);
  }

  /// @notice Returns the symbol of the token
  /// @return The token symbol
  function symbol() public view returns (string memory) {
    return hub.symbol(tokenId);
  }

  /// @notice Returns the decimals of the token
  /// @return The token decimals
  function decimals() public view returns (uint8) {
    return hub.decimals(tokenId);
  }

  /// @notice Returns the token URI
  /// @return The token URI
  function tokenURI() public view returns (string memory) {
    return hub.tokenURI(tokenId);
  }

  /// @notice Returns the total supply of the token
  /// @return The total supply
  function totalSupply() public view returns (uint256) {
    return hub.totalSupply(tokenId);
  }

  /// @notice Returns the balance of an account
  /// @param account The account address
  /// @return The balance amount
  function balanceOf(address account) public view returns (uint256) {
    return hub.balanceOf(account, tokenId);
  }

  /// @notice Returns the allowance amount for a spender
  /// @param owner The owner address
  /// @param spender The spender address
  /// @return The allowance amount
  function allowance(
    address owner,
    address spender
  ) public view returns (uint256) {
    return hub.allowance(owner, spender, tokenId);
  }

  /// @notice Approves a spender to spend tokens
  /// @param spender The spender address
  /// @param value The amount to approve
  /// @return True if successful
  function approve(address spender, uint256 value) public returns (bool) {
    bool success = hub.approveFor(msg.sender, spender, tokenId, value);
    if (success) {
      emit Approval(msg.sender, spender, value);
    }
    return success;
  }

  /// @notice Transfers tokens to another address
  /// @param to The recipient address
  /// @param value The amount to transfer
  /// @return True if successful
  function transfer(address to, uint256 value) public returns (bool) {
    bool success = hub.transferFrom(msg.sender, to, tokenId, value);
    if (success) {
      emit Transfer(msg.sender, to, value);
    }
    return success;
  }

  /// @notice Transfers tokens from one address to another
  /// @param from The sender address
  /// @param to The recipient address
  /// @param value The amount to transfer
  /// @return True if successful
  function transferFrom(
    address from,
    address to,
    uint256 value
  ) public returns (bool) {
    // Check allowance unless the spender is the owner
    if (msg.sender != from) {
      uint256 currentAllowance = hub.allowance(from, msg.sender, tokenId);
      if (currentAllowance < type(uint256).max) {
        if (currentAllowance < value) {
          revert ERC20ViewInsufficientAllowance(
            msg.sender,
            currentAllowance,
            value
          );
        }
        hub.approveFor(from, msg.sender, tokenId, currentAllowance - value);
      }
    }

    // Execute the transfer on the Hub
    bool success = hub.transferFrom(from, to, tokenId, value);
    if (success) {
      emit Transfer(from, to, value);
    }
    return success;
  }

  /*//////////////////////////////////////////////////////////////
                          HUB EVENT EMISSION
    //////////////////////////////////////////////////////////////*/

  /// @notice Emits a transfer event (only callable by the hub)
  /// @param from The sender address
  /// @param to The recipient address
  /// @param value The amount transferred
  function emitTransferEvent(address from, address to, uint256 value) external {
    if (msg.sender == address(hub)) {
      emit Transfer(from, to, value);
    }
  }

  /// @notice Emits an approval event (only callable by the hub)
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param value The approved amount
  function emitApprovalEvent(
    address owner,
    address spender,
    uint256 value
  ) external {
    if (msg.sender == address(hub)) {
      emit Approval(owner, spender, value);
    }
  }
}

contracts/RelayHub.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/Strings.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "./ERC20View.sol";

/// @title IERC20View
/// @author Relay Protocol
/// @notice Interface for ERC20View contract
interface IERC20View {
  /// @notice Emits a transfer event
  /// @param from The sender address
  /// @param to The recipient address
  /// @param value The amount transferred
  function emitTransferEvent(address from, address to, uint256 value) external;

  /// @notice Emits an approval event
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param value The approved amount
  function emitApprovalEvent(
    address owner,
    address spender,
    uint256 value
  ) external;
}

/// @title RelayHub
/// @author Relay Protocol
/// @notice Based on Solmate standard ERC6909 implementation. (https://github.com/transmissions11/solmate/blob/main/src/tokens/ERC6909.sol)
contract RelayHub is AccessControl, EIP712 {
  using Strings for uint256;

  /*//////////////////////////////////////////////////////////////
                            CUSTOM ERRORS
    //////////////////////////////////////////////////////////////*/

  /// @notice Error thrown when non-ERC20View tries to call approveFor
  /// @param caller The address that attempted to call approveFor
  /// @param expectedERC20View The expected ERC20View address for the token
  error OnlyERC20ViewCanCallApproveFor(
    address caller,
    address expectedERC20View
  );

  /// @notice Error thrown when permit deadline has expired
  error PermitDeadlineExpired();

  /// @notice Error thrown when permit signature is invalid
  error InvalidPermitSignature();

  /// @notice Error thrown when permit owner is the zero address
  error InvalidPermitOwner();

  /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

  /// @notice Emitted when an operator is set for an owner
  event OperatorSet(
    address indexed owner,
    address indexed operator,
    bool approved
  );

  /// @notice Emitted when an approval is made
  event Approval(
    address indexed owner,
    address indexed spender,
    uint256 indexed id,
    uint256 amount
  );

  /// @notice Emitted when a transfer occurs
  event Transfer(
    address caller,
    address indexed from,
    address indexed to,
    uint256 indexed id,
    uint256 amount
  );

  struct TokenMetadata {
    string name;
    string symbol;
    uint8 decimals;
    string originFamily;
    uint256 originChainId;
    string originAsset;
  }

  /*//////////////////////////////////////////////////////////////
                             ERC6909 STORAGE
    //////////////////////////////////////////////////////////////*/

  mapping(address => mapping(address => bool)) internal _isOperator;

  /// @notice Mapping of owner to token ID to balance
  mapping(address => mapping(uint256 => uint256)) public balanceOf;

  /// @notice Mapping of owner to spender to token ID to allowance
  mapping(address => mapping(address => mapping(uint256 => uint256)))
    public allowance;

  /// @notice Mapping of token ID to total supply
  mapping(uint256 => uint256) public totalSupply;

  /// @notice Mapping of owner to nonce for permit signatures
  mapping(address => uint256) public nonces;

  /*//////////////////////////////////////////////////////////////
                          ERC20VIEW STORAGE
    //////////////////////////////////////////////////////////////*/

  // tokenId => ERC20View address
  /// @notice Mapping of token ID to ERC20View contract address
  mapping(uint256 => address) public erc20Views;

  /*//////////////////////////////////////////////////////////////
                        ERC20VIEW EVENTS
    //////////////////////////////////////////////////////////////*/

  /// @notice Emitted when an ERC20View is created
  event ERC20ViewCreated(uint256 indexed tokenId, address indexed erc20View);
  /// @notice Mapping of token ID to token metadata
  mapping(uint256 => TokenMetadata) public tokenMetadata;

  /// @notice Contract URI for metadata
  string public contractURI = "";

  /*//////////////////////////////////////////////////////////////
                             ROLES
    //////////////////////////////////////////////////////////////*/

  /// @notice Role for operators
  bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
  /// @notice Role for editors
  bytes32 public constant EDITOR_ROLE = keccak256("EDITOR_ROLE");
  /// @notice Role for administrators
  bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

  /*//////////////////////////////////////////////////////////////
                          EIP712 CONSTANTS
    //////////////////////////////////////////////////////////////*/

  /// @notice EIP712 typehash for permit
  bytes32 public constant PERMIT_TYPEHASH =
    keccak256(
      "Permit(address owner,address spender,uint256 tokenId,uint256 value,uint256 nonce,uint256 deadline)"
    );

  /*//////////////////////////////////////////////////////////////
                             CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

  /// @notice Constructor for RelayHub contract
  /// @param adminAddress The address to grant admin role
  constructor(address adminAddress) EIP712("RelayHub", "1") {
    _setRoleAdmin(OPERATOR_ROLE, ADMIN_ROLE);
    _setRoleAdmin(EDITOR_ROLE, ADMIN_ROLE);
    _setRoleAdmin(ADMIN_ROLE, ADMIN_ROLE);
    _grantRole(ADMIN_ROLE, adminAddress);
  }

  /*//////////////////////////////////////////////////////////////
                              ERC6909 LOGIC
    //////////////////////////////////////////////////////////////*/

  /// @notice Checks if an address is an operator for an account
  /// @param account The account address
  /// @param operator The operator address
  /// @return True if the operator is authorized
  function isOperator(
    address account,
    address operator
  ) public view returns (bool) {
    return hasRole(OPERATOR_ROLE, operator) || _isOperator[account][operator];
  }

  /// @notice Internal function to set an operator for an account
  /// @param account The account address
  /// @param operator The operator address
  /// @param approved Whether to approve the operator
  /// @return result True if successful
  function _setOperatorFor(
    address account,
    address operator,
    bool approved
  ) internal returns (bool result) {
    _isOperator[account][operator] = approved;
    emit OperatorSet(account, operator, approved);
    return true;
  }

  /// @notice Sets an operator for an account (only callable by OPERATOR_ROLE)
  /// @param account The account address
  /// @param operator The operator address
  /// @param approved Whether to approve the operator
  /// @return result True if successful
  function setOperatorFor(
    address account,
    address operator,
    bool approved
  ) public onlyRole(OPERATOR_ROLE) returns (bool result) {
    return _setOperatorFor(account, operator, approved);
  }

  /// @notice Sets an operator for the caller
  /// @param operator The operator address
  /// @param approved Whether to approve the operator
  /// @return result True if successful
  function setOperator(
    address operator,
    bool approved
  ) public returns (bool result) {
    return _setOperatorFor(msg.sender, operator, approved);
  }

  /// @notice Transfers tokens to another address
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to transfer
  /// @return result True if successful
  function transfer(
    address receiver,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    balanceOf[msg.sender][id] -= amount;

    balanceOf[receiver][id] += amount;

    emit Transfer(msg.sender, msg.sender, receiver, id, amount);
    _emitERC20ViewEvent(id, msg.sender, receiver, amount);

    return true;
  }

  /// @notice Transfers tokens from one address to another
  /// @param sender The sender address
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to transfer
  /// @return result True if successful
  function transferFrom(
    address sender,
    address receiver,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    if (
      msg.sender != sender &&
      !isOperator(sender, msg.sender) &&
      erc20Views[id] != msg.sender
    ) {
      uint256 allowed = allowance[sender][msg.sender][id];
      if (allowed != type(uint256).max)
        allowance[sender][msg.sender][id] = allowed - amount;
    }

    balanceOf[sender][id] -= amount;

    balanceOf[receiver][id] += amount;

    emit Transfer(msg.sender, sender, receiver, id, amount);
    _emitERC20ViewEvent(id, sender, receiver, amount);

    return true;
  }

  /// @notice Approves a spender to spend tokens
  /// @param spender The spender address
  /// @param id The token ID
  /// @param amount The amount to approve
  /// @return result True if successful
  function approve(
    address spender,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    allowance[msg.sender][spender][id] = amount;

    emit Approval(msg.sender, spender, id, amount);
    _emitERC20ViewApprovalEvent(id, msg.sender, spender, amount);

    return true;
  }

  /// @notice Approves a spender to spend tokens on behalf of owner (only callable by ERC20View)
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param id The token ID
  /// @param amount The amount to approve
  /// @return result True if successful
  function approveFor(
    address owner,
    address spender,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    if (erc20Views[id] != msg.sender) {
      revert OnlyERC20ViewCanCallApproveFor(msg.sender, erc20Views[id]);
    }

    allowance[owner][spender][id] = amount;

    emit Approval(owner, spender, id, amount);
    // Note: The ERC20View will emit its own Approval event

    return true;
  }

  /// @notice Permits a spender to spend tokens via signature (EIP712)
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param tokenId The token ID
  /// @param value The allowance amount
  /// @param deadline The deadline timestamp
  /// @param v The recovery byte of the signature
  /// @param r Half of the ECDSA signature pair
  /// @param s Half of the ECDSA signature pair
  function permit(
    address owner,
    address spender,
    uint256 tokenId,
    uint256 value,
    uint256 deadline,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) public {
    if (owner == address(0)) {
      revert InvalidPermitOwner();
    }

    if (block.timestamp > deadline) {
      revert PermitDeadlineExpired();
    }

    uint256 ownerNonce = nonces[owner];

    bytes32 structHash = keccak256(
      abi.encode(
        PERMIT_TYPEHASH,
        owner,
        spender,
        tokenId,
        value,
        ownerNonce,
        deadline
      )
    );

    bytes32 hash = _hashTypedDataV4(structHash);

    address signer = ECDSA.recover(hash, v, r, s);

    if (signer != owner) {
      revert InvalidPermitSignature();
    }

    nonces[owner] = ownerNonce + 1;

    allowance[owner][spender][tokenId] = value;

    emit Approval(owner, spender, tokenId, value);
    _emitERC20ViewApprovalEvent(tokenId, owner, spender, value);
  }

  /// @notice Mints tokens to a receiver (only callable by OPERATOR_ROLE)
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to mint
  /// @return result True if successful
  function mint(
    address receiver,
    uint256 id,
    uint256 amount
  ) public onlyRole(OPERATOR_ROLE) returns (bool result) {
    _mint(receiver, id, amount);
    return true;
  }

  /// @notice Burns tokens from a sender (only callable by OPERATOR_ROLE)
  /// @param sender The sender address
  /// @param id The token ID
  /// @param amount The amount to burn
  /// @return result True if successful
  function burn(
    address sender,
    uint256 id,
    uint256 amount
  ) public onlyRole(OPERATOR_ROLE) returns (bool result) {
    _burn(sender, id, amount);
    return true;
  }

  /// @notice Sets token metadata (only callable by EDITOR_ROLE)
  /// @param id The token ID
  /// @param metadata The token metadata
  function setTokenMetadata(
    uint256 id,
    TokenMetadata calldata metadata
  ) public onlyRole(EDITOR_ROLE) {
    tokenMetadata[id] = metadata;
  }

  /// @notice Returns the name of a token
  /// @param id The token ID
  /// @return The token name
  function name(uint256 id) public view returns (string memory) {
    return tokenMetadata[id].name;
  }

  /// @notice Returns the symbol of a token
  /// @param id The token ID
  /// @return The token symbol
  function symbol(uint256 id) public view returns (string memory) {
    return tokenMetadata[id].symbol;
  }

  /// @notice Returns the decimals of a token
  /// @param id The token ID
  /// @return The token decimals
  function decimals(uint256 id) public view returns (uint8) {
    if (tokenMetadata[id].decimals == 0) {
      return 18;
    }
    return tokenMetadata[id].decimals;
  }

  /// @notice Sets the contract URI (only callable by EDITOR_ROLE)
  /// @param uri The contract URI
  function setContractURI(string calldata uri) public onlyRole(EDITOR_ROLE) {
    contractURI = uri;
  }

  /// @notice Returns the token URI
  /// @param id The token ID
  /// @return The token URI
  function tokenURI(uint256 id) public view returns (string memory) {
    return string.concat(contractURI, "/", id.toString());
  }

  /*//////////////////////////////////////////////////////////////
                              ERC165 LOGIC
    //////////////////////////////////////////////////////////////*/

  /// @notice Returns the domain separator for EIP712
  /// @return The domain separator
  function DOMAIN_SEPARATOR() external view returns (bytes32) {
    return _domainSeparatorV4();
  }

  /// @notice Checks if the contract supports an interface
  /// @param interfaceId The interface ID to check
  /// @return result True if the interface is supported
  function supportsInterface(
    bytes4 interfaceId
  ) public pure override(AccessControl) returns (bool result) {
    return
      interfaceId == 0x01ffc9a7 || // ERC165 Interface ID for ERC165
      interfaceId == 0x0f632fb3; // ERC165 Interface ID for ERC6909
  }

  /*//////////////////////////////////////////////////////////////
                        INTERNAL MINT/BURN LOGIC
    //////////////////////////////////////////////////////////////*/

  /// @notice Internal function to mint tokens
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to mint
  function _mint(address receiver, uint256 id, uint256 amount) internal {
    balanceOf[receiver][id] += amount;
    if (totalSupply[id] == 0) {
      _createERC20View(id);
    }
    totalSupply[id] += amount;

    emit Transfer(msg.sender, address(0), receiver, id, amount);
    _emitERC20ViewEvent(id, address(0), receiver, amount);
  }

  /// @notice Internal function to burn tokens
  /// @param sender The sender address
  /// @param id The token ID
  /// @param amount The amount to burn
  function _burn(address sender, uint256 id, uint256 amount) internal {
    balanceOf[sender][id] -= amount;
    totalSupply[id] -= amount;

    emit Transfer(msg.sender, sender, address(0), id, amount);
    _emitERC20ViewEvent(id, sender, address(0), amount);
  }

  /*//////////////////////////////////////////////////////////////
                            INTERNAL HELPERS
  //////////////////////////////////////////////////////////////*/

  /// @notice Internal function to emit ERC20View events
  /// @param id The token ID
  /// @param from The sender address
  /// @param to The recipient address
  /// @param amount The amount transferred
  function _emitERC20ViewEvent(
    uint256 id,
    address from,
    address to,
    uint256 amount
  ) internal {
    address erc20ViewAddress = erc20Views[id];
    if (msg.sender != erc20ViewAddress) {
      IERC20View(erc20ViewAddress).emitTransferEvent(from, to, amount);
    }
  }

  /// @notice Internal function to emit ERC20View approval events
  /// @param id The token ID
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param amount The approved amount
  function _emitERC20ViewApprovalEvent(
    uint256 id,
    address owner,
    address spender,
    uint256 amount
  ) internal {
    address erc20ViewAddress = erc20Views[id];
    if (msg.sender != erc20ViewAddress) {
      IERC20View(erc20ViewAddress).emitApprovalEvent(owner, spender, amount);
    }
  }

  /// @notice Internal function to create an ERC20View contract
  /// @param tokenId The token ID
  /// @return The address of the created ERC20View contract
  function _createERC20View(uint256 tokenId) internal returns (address) {
    if (erc20Views[tokenId] != address(0)) {
      return erc20Views[tokenId];
    }

    ERC20View erc20View = new ERC20View(tokenId);

    address erc20ViewAddress = address(erc20View);
    erc20Views[tokenId] = erc20ViewAddress;

    emit ERC20ViewCreated(tokenId, erc20ViewAddress);
    return erc20ViewAddress;
  }
}

